content.content:
     1	package hotel.reservations;
     2	
     3	import hotel.documents.DocumentFactory;
     4	import hotel.documents.ReservationReceipt;
     5	import hotel.messages.EmailSender;
     6	import hotel.rooms.Room;
     7	import hotel.rooms.Rooms;
     8	import java.math.BigDecimal;
     9	
    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	    private final DocumentFactory documents = new DocumentFactory();
    20	
    21	    public ReservationService(
    22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    23	        this.rooms = rooms;
    24	        this.store = store;
    25	        this.priceCalculator = priceCalculator;
    26	        this.emailSender = emailSender;
    27	    }
    28	
    29	    public synchronized Reservation create(NewReservation request) {
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    32	        }
    33	        if (request.guests() < 1) {
    34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    35	        }
    36	        Room room = rooms.find(request.roomNumber())
    37	                .orElseThrow(() -> new HotelException(
    38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    39	        if (request.guests() > room.capacity()) {
    40	            throw new HotelException(
    41	                    ErrorCode.CAPACITY_EXCEEDED,
    42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    43	        }
    44	        boolean roomTaken = store.all().stream()
    45	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    46	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    47	        if (roomTaken) {
    48	            throw new HotelException(
    49	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    50	        }
    51	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    52	        Reservation reservation = new Reservation(store.nextId(), request, price);
    53	        store.save(reservation);
    54	        return reservation;
    55	    }
    56	
    57	    public Reservation find(long reservationId) {
    58	        return store.find(reservationId)
    59	                .orElseThrow(() -> new HotelException(
    60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    61	    }
    62	
    63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        ReservationReceipt receipt = documents.issue(reservation, roomOf(reservation));
    71	        emailSender.send(
    72	                reservation.guest().email(),
    73	                "Reserva confirmada - " + HOTEL_NAME,
    74	                confirmationEmailBody(reservation, receipt));
    75	        return reservation;
    76	    }
    77	
    78	    /**
    79	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    80	     * reservation was never paid, so nothing comes back).
    81	     */
    82	    public synchronized Reservation cancel(long reservationId) {
    83	        Reservation reservation = find(reservationId);
    84	        if (reservation.status() != ReservationStatus.PENDING
    85	                && reservation.status() != ReservationStatus.CONFIRMED) {
    86	            throw notAllowed(reservation, "cancel");
    87	        }
    88	        BigDecimal refund = switch (reservation.ratePlan()) {
    89	            case STANDARD -> reservation.amountPaid();
    90	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    91	        };
    92	        reservation.cancel(refund);
    93	        return reservation;
    94	    }
    95	
    96	    public synchronized Reservation checkIn(long reservationId) {
    97	        Reservation reservation = find(reservationId);
    98	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    99	            throw notAllowed(reservation, "check in");
   100	        }
   101	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   102	        return reservation;
   103	    }
   104	
   105	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   106	    public synchronized ReservationReceipt checkOut(long reservationId) {
   107	        Reservation reservation = find(reservationId);
   108	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   109	            throw notAllowed(reservation, "check out");
   110	        }
   111	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   112	        return documents.issue(reservation, roomOf(reservation));
   113	    }
   114	
   115	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   116	    public ReservationReceipt receiptCopy(long reservationId) {
   117	        Reservation reservation = find(reservationId);
   118	        if (!reservation.isPaid()) {
   119	            throw notAllowed(reservation, "issue a receipt for");
   120	        }
   121	        return documents.issue(reservation, roomOf(reservation));
   122	    }
   123	
   124	    private Room roomOf(Reservation reservation) {
   125	        return rooms.find(reservation.roomNumber()).orElseThrow();
   126	    }
   127	
   128	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   129	        return "Olá, " + reservation.guest().name() + "!\n\n"
   130	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   131	                + receipt.text() + "\n"
   132	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   133	                + "Até breve!\n";
   134	    }
   135	
   136	    private static HotelException notAllowed(Reservation reservation, String operation) {
   137	        return new HotelException(
   138	                ErrorCode.OPERATION_NOT_ALLOWED,
   139	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   140	    }
   141	}
+
+    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
+    public ReservationReceipt receiptCopy(long reservationId) {
+        Reservation reservation = find(reservationId);
+        if (!reservation.isPaid()) {
+            throw notAllowed(reservation, "issue a receipt for");
+        }
+        return documents.issue(reservation, roomOf(reservation));
+    }
+
+    private Room roomOf(Reservation reservation) {
+        return rooms.find(reservation.roomNumber()).orElseThrow();
+    }
+
+    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
+        return "Olá, " + reservation.guest().name() + "!\n\n"
+                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
+                + receipt.text() + "\n"
+                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
+                + "Até breve!\n";
+    }
+
+    private static HotelException notAllowed(Reservation reservation, String operation) {
+        return new HotelException(
+                ErrorCode.OPERATION_NOT_ALLOWED,
+                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
+    }
+}
